{"implementation": "def solve(case):
    if 'payload' in case:
        payload = case['payload']
    else:
        payload = case

    nodes_list = payload.get('nodes')
    if nodes_list is None:
        raise ValueError('Missing nodes field in payload')

    required_symbols_list = payload.get('required_symbols')
    if required_symbols_list is None:
        raise ValueError('Missing required_symbols field in payload')

    required_symbols = set(required_symbols_list)

    nodes = {}
    for n in nodes_list:
        for field in ['id', 'parent', 'symbol', 'depth', 'removable', 'utility']:
            if field not in n:
                raise ValueError('Missing field ' + field + ' in node')
        nid = n['id']
        if nid in nodes:
            raise ValueError('Duplicate node id: ' + nid)
        nodes[nid] = n

    children = {nid: [] for nid in nodes}
    for n in nodes_list:
        parent = n['parent']
        if parent is not None:
            if parent not in nodes:
                raise ValueError('Parent not found for node ' + n['id'])
            children[parent].append(n['id'])

    initial_symbols = {n['symbol'] for n in nodes_list}
    for sym in required_symbols:
        if sym not in initial_symbols:
            raise ValueError('Required symbol not present in tree: ' + sym)

    sorted_nodes = sorted(nodes_list, key=lambda n: (-n['depth'], n['id']))

    maintained = set(nodes.keys())
    removal_order = []

    for n in sorted_nodes:
        nid = n['id']

        if not n['removable']:
            continue

        if n['symbol'] in required_symbols:
            continue

        if any(child in maintained for child in children[nid]):
            continue

        test_maintained = maintained - {nid}
        symbols_present = {nodes[mid]['symbol'] for mid in test_maintained}

        if required_symbols.issubset(symbols_present):
            maintained.discard(nid)
            removal_order.append(nid)

    retained_ids = sorted(maintained)

    return {
        'retained_ids': retained_ids,
        'removal_order': removal_order
    }
